import { useEffect, useMemo, useState, useRef } from "react";
import {
  Form,
  Button,
  Row,
  Col,
  Container,
  Alert,
  Card,
  Nav,
  Navbar
} from "react-bootstrap";
import { getCourses } from "../api/api";
import { useNavigate } from "react-router-dom";

function SyllabusManager() {
  const inputRef = useRef(null);

  const navigate = useNavigate();
  const [courses, setCourses] = useState([]);
  const [error, setError] = useState("");

  const [search, setSearch] = useState("");
  const [semesterFilter, setSemesterFilter] = useState("");

  const loadCourses = () => {
    getCourses()
      .then((data) => setCourses(data))
      .catch(() => setError("Không thể tải danh sách khóa học."));
  };

  useEffect(() => {
    loadCourses();
  }, []);

  const semesters = useMemo(
    () => [...new Set(courses.map((c) => c.semester))],
    [courses],
  );

  const filteredCourses = useMemo(() => {
    const keyword = search.trim().toLowerCase();
    return courses.filter((c) => {
      const matchesKeyword =
        !keyword ||
        c.code?.toLowerCase().includes(keyword) ||
        c.nameEn?.toLowerCase().includes(keyword) ||
        c.nameVi?.toLowerCase().includes(keyword);
      const matchesSemester = !semesterFilter || c.semester === semesterFilter;
      return matchesKeyword && matchesSemester;
    });
  }, [courses, search, semesterFilter]);

  return (
    <Container className="py-4">
        <Navbar bg="dark" data-bs-theme="dark">
        <Container>
          <Nav className="me-auto">
            <Nav.Link href="#course">Courses</Nav.Link>
            <Nav.Link href="#project">Projects</Nav.Link>
            <Nav.Link href="#pricing">Review</Nav.Link>
            <Nav.Link href="#title">Title Confirmation</Nav.Link>
            <Nav.Link href="#reference">Reference</Nav.Link>
          </Nav>
        </Container>
      </Navbar>
        <p>Welcome back Lecturer</p>
      <h2 className="mb-3">My Courses</h2>

      {error && <Alert variant="danger">{error}</Alert>}

      <Row className="mb-3 g-2 align-items-end">
        <Col md={5}>
          <Form.Control ref={inputRef}
            placeholder="Tìm theo mã hoặc tên khóa học..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Col>
        <Col md={4}>
          <Form.Label>Semester</Form.Label>
          <Form.Select
            value={semesterFilter}
            onChange={(e) => setSemesterFilter(e.target.value)}
          >
            <option value="">Tất cả</option>
            {semesters.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </Form.Select>
        </Col>
        <Col>
          {" "}
          <Button
            variant="info"
            onClick={() => {
                inputRef.current.focus();;
              setSearch("");
              setSemesterFilter("");
            }}
          >
            Refresh
          </Button>
        </Col>
      </Row>

      {filteredCourses.length === 0 && (
        <div className="text-center text-muted py-4">
          Không có khóa học nào.
        </div>
      )}

      <Row>
        {filteredCourses.map((course) => (
          <Col md={4} className="mb-2" key={course.id}>
            <Card>
              <Card.Body>
                <div style={{ display: "flex", flexDirection: "column" }}>
                  <div style={{ display: "flex", justifyContent: "space-between" }}>
                    <p>{course.badge}</p>
                    <p>{course.category}</p>
                  </div>
                  <Card.Text>
                    {course.code}
                    <h5>{course.nameEn}</h5>
                    {course.nameVi}
                    <div className="text-muted small"></div>
                  </Card.Text>
                  <div style={{ display: "flex", justifyContent: "space-between" }}>
                    <strong>Get started</strong>
                    <Button
                      onClick={() => navigate(`/detail/${course.id}`)}
                      variant="primary"
                    >
                      →
                    </Button>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default SyllabusManager;
